const rows = $input.all();
// skip blank rows (no business name) so they never burn searches or jam the queue
const pending = rows.filter(i => String(i.json.status || '').toLowerCase() === 'pending' && String(i.json.business_name || '').trim() !== '').slice(0, 20);
return pending.map(i => ({ json: i.json }));

const item = $('Pick First 20 Pending').item.json;
const DIRECTORY = ['facebook.com','instagram.com','yelp.com','nextdoor.com','linktr.ee','sites.google.com','business.site','angi.com','homeadvisor.com','thumbtack.com','houzz.com','bbb.org','yellowpages.com','porch.com','mapquest.com','google.com','goo.gl','maps.app.goo.gl','linkedin.com','x.com','twitter.com','tiktok.com','manta.com','chamberofcommerce.com'];
const isRealDomain = (url) => {
  if (!url) return false;
  let u = String(url).trim();
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
  let host;
  try { host = new URL(u).hostname.toLowerCase(); } catch (e) { return false; }
  if (!host || !host.includes('.')) return false;
  return !DIRECTORY.some(d => host === d || host.endsWith('.' + d));
};
const blank = { skip_searches: true, hard_reject: 'Website linked through Google Business Profile', website_found_url: '', q1:'',q2:'',q3:'',q4:'',q5:'',q6:'',q7:'' };
if (isRealDomain(item.listed_website)) {
  return [{ json: Object.assign({}, item, blank, { website_found_url: String(item.listed_website) }) }];
}
const urls = String(item.gbp_links || '').match(/https?:\/\/[^\s,;"']+/gi) || [];
for (const u of urls) {
  if (isRealDomain(u)) {
    return [{ json: Object.assign({}, item, blank, { website_found_url: u }) }];
  }
}
const name = String(item.business_name || '').trim();
const shortName = name.split(/\s+/).slice(0, 2).join(' ');
let city = String(item.city || '').trim();
const address = String(item.address || '').trim();
if (!city && address) {
  const m = address.match(/,s*([A-Za-z][A-Za-z .'-]+),s*[A-Z]{2} /);
  if (m) city = m[1].trim();
}
const d10 = String(item.phone || '').replace(/\D/g, '').slice(-10);
const need_phone_lookup = d10.length === 10 && (!city || !address);
const q = s => '"' + s + '"';
let q1 = '', q2 = '', q3 = '', q4 = '', q5 = '', q6 = '', q7 = '';
if (name) q1 = q(name);
if (name && city) q2 = q(name + ' ' + city + ' VA');
if (name) q3 = q(name + ' Virginia');
if (d10.length === 10) {
  const f1 = '(' + d10.slice(0,3) + ') ' + d10.slice(3,6) + '-' + d10.slice(6);
  const f2 = d10.slice(0,3) + '-' + d10.slice(3,6) + '-' + d10.slice(6);
  q4 = q(f1) + ' OR ' + q(f2) + ' OR ' + q(d10);
}
if (address && shortName) q5 = q(address) + ' ' + q(shortName);
if (name) q6 = q(name) + ' (site:facebook.com OR site:instagram.com OR site:linkedin.com OR site:x.com OR site:tiktok.com)';
if (name) q7 = q(name) + ' (site:yelp.com OR site:angi.com OR site:homeadvisor.com OR site:bbb.org OR site:thumbtack.com OR site:porch.com OR site:houzz.com OR site:nextdoor.com OR site:yellowpages.com OR site:chamberofcommerce.com)';
return [{ json: Object.assign({}, item, { city: city, skip_searches: false, hard_reject: '', website_found_url: '', need_phone_lookup: need_phone_lookup, q1,q2,q3,q4,q5,q6,q7 }) }];

const base = $('Layer 4 GBP Check + Queries').item.json;
let city = String(base.city || '').trim();
let address = String(base.address || '').trim();
let filled = [];
try {
  const s = $('Phone Lookup Search').item.json;
  const cand = [];
  if (s.knowledgeGraph && s.knowledgeGraph.address) cand.push(String(s.knowledgeGraph.address));
  const places = Array.isArray(s.places) ? s.places : [];
  for (const p of places) { if (p && p.address) cand.push(String(p.address)); }
  for (const cand0 of cand) {
    const parts = cand0.split(',').map(x => x.trim()).filter(Boolean);
    const stIdx = parts.findIndex(p => /^[A-Z]{2}(\s+\d{5}(-\d{4})?)?$/.test(p));
    if (stIdx > 0) {
      if (!city) { city = parts[stIdx - 1]; filled.push('city from phone lookup'); }
      if (!address) { address = parts.slice(0, stIdx + 1).join(', '); filled.push('address from phone lookup'); }
      break;
    }
  }
} catch (e) {}
const shortName = String(base.business_name || '').trim().split(/\s+/).slice(0, 2).join(' ');
const q = s => '"' + s + '"';
const q2 = (base.business_name && city) ? q(base.business_name + ' ' + city + ' VA') : '';
const q5 = (address && shortName) ? q(address) + ' ' + q(shortName) : '';
return [{ json: Object.assign({}, base, { city: city, address: address, q2: q2, q5: q5, geo_filled: filled.join('; ') }) }];

const lead = $('Enrich City + Address').item.json;
const fetchNode = (n) => { try { return $(n).item.json; } catch (e) { return { __error: true }; } };
const isErr = j => !j || j.__error || j.error || j.errorMessage;
const s1 = fetchNode('Search Q1 Name');
const s2 = fetchNode('Search Q2 Name City');
const s3 = fetchNode('Search Q3 Name State');
const s4 = fetchNode('Search Q4 Phone');
const s5 = fetchNode('Search Q5 Address');
const s6 = fetchNode('Search Q6 Social');
const s7 = fetchNode('Search Q7 Directories');
const err_q1 = lead.q1 ? isErr(s1) : false;
const err_q2 = lead.q2 ? isErr(s2) : false;
const err_q4 = lead.q4 ? isErr(s4) : false;
const results = [];
for (const s of [s1,s2,s3,s4,s5,s6,s7]) {
  if (isErr(s)) continue;
  const org = Array.isArray(s.organic) ? s.organic : [];
  for (const o of org.slice(0, 10)) {
    results.push({ link: o.link || '', title: o.title || '', snippet: o.snippet || '' });
  }
}
const DIRECTORY = ['facebook.com','instagram.com','yelp.com','nextdoor.com','linktr.ee','sites.google.com','business.site','angi.com','homeadvisor.com','thumbtack.com','houzz.com','bbb.org','yellowpages.com','porch.com','mapquest.com','google.com','linkedin.com','x.com','twitter.com','tiktok.com','manta.com','chamberofcommerce.com'];
const isRealDomain = (url) => {
  if (!url) return false;
  let u = String(url).trim();
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
  let host;
  try { host = new URL(u).hostname.toLowerCase(); } catch (e) { return false; }
  if (!host || !host.includes('.')) return false;
  return !DIRECTORY.some(d => host === d || host.endsWith('.' + d));
};
let kgReject = '';
let kgUrl = '';
for (const s of [s1,s2,s3]) {
  if (isErr(s)) continue;
  if (s.knowledgeGraph && isRealDomain(s.knowledgeGraph.website)) { kgReject = 'Website linked through Google Business Profile'; kgUrl = s.knowledgeGraph.website; }
  const places = Array.isArray(s.places) ? s.places : [];
  for (const p of places) { if (p && isRealDomain(p.website)) { kgReject = 'Website linked through Google Business Profile'; kgUrl = p.website; } }
}
const TRADE = ['llc','inc','co','services','service','company','the','and','of'];
const rawWords = String(lead.business_name || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w && TRADE.indexOf(w) === -1);
const city = String(lead.city || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const joined = rawWords.join('');
const hyphenated = rawWords.join('-');
const initials = rawWords.map(w => w[0]).join('');
const firstTwo = rawWords.slice(0, 2).join('');
const tradeWord = rawWords.length > 1 ? rawWords[rawWords.length - 1] : '';
const bases = [];
const push = b => { if (b && b.length > 1 && bases.indexOf(b) === -1) bases.push(b); };
push(joined); push(hyphenated);
if (city) { push(joined + city); push(joined + '-' + city); }
push(joined + 'va'); push(joined + '-va');
if (tradeWord && initials) push(initials + tradeWord);
if (firstTwo && firstTwo !== joined) push(firstTwo);
const tlds = ['.com', '.net', '.biz', '.us', '.co'];
const domains = [];
for (const b of bases) { for (const t of tlds) { if (domains.length < 20) domains.push(b + t); } }
const distinctive = rawWords.filter(w => w.length > 3).slice(0, 4);
return [{ json: Object.assign({}, lead, {
  hard_reject: lead.hard_reject || kgReject,
  website_found_url: lead.website_found_url || kgUrl,
  search_results: JSON.stringify(results).slice(0, 12000),
  result_count: results.length,
  err_q1: err_q1, err_q2: err_q2, err_q4: err_q4,
  candidate_domains: domains,
  domain_probe_count: domains.length,
  distinctive_words: distinctive,
  phone_tail: String(lead.phone || '').replace(/\D/g, '').slice(-7)
}) }];

const lead = $json;
const out = [];
for (const d of (lead.candidate_domains || [])) {
  out.push({ json: { domain: d } });
}
if (!out.length) out.push({ json: { domain: '' } });
return out;

const lead = $('Collect Results + Domain Candidates').item.json;
const reqDomains = $('Split Domain List').all().map(i => i.json.domain);
const probes = $input.all().map(i => (i && i.json) ? i.json : {});
const PARKED = ['domain is for sale','buy this domain','parked','sedo','hugedomains','afternic','dan.com','this domain may be for sale'];
let domainReject = '';
let domainUrl = '';
const summary = [];
for (let k = 0; k < probes.length; k++) {
  const p = probes[k];
  const req = reqDomains[k] || '';
  const status = p.statusCode || 0;
  const body = String(p.body || '').toLowerCase().slice(0, 300000);
  if (!req || status !== 200 || !body) continue;
  if (PARKED.some(t => body.indexOf(t) !== -1)) { summary.push(req + ' parked/for-sale'); continue; }
  const words = (lead.distinctive_words || []);
  const hits = words.filter(w => body.indexOf(w) !== -1).length;
  const phoneHit = lead.phone_tail && lead.phone_tail.length === 7 && body.indexOf(lead.phone_tail) !== -1;
  if (hits >= 2 || phoneHit) { domainReject = 'Website found through domain search'; domainUrl = 'https://' + req; }
  summary.push(req + ' live, ' + hits + ' word hits' + (phoneHit ? ', phone match' : ''));
}
return [{ json: Object.assign({}, lead, {
  hard_reject: lead.hard_reject || domainReject,
  website_found_url: lead.website_found_url || domainUrl,
  domain_summary: summary.join('; ') || 'no candidate domains resolved'
}) }];

const lead = $('Domain Match Verdict').item.json;
let ai = { website_found: false, website_url: '', reject_reason: '', confidence_no_website: 0, notes: '' };
try {
  const j = $json;
  let text = '';
  if (typeof j.content === 'string') text = j.content;
  else if (Array.isArray(j.content)) text = j.content.map(b => (b && b.text) ? b.text : '').join(' ');
  else if (typeof j.text === 'string') text = j.text;
  const m = text.match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    ai = {
      website_found: !!parsed.website_found,
      website_url: parsed.website_url || '',
      reject_reason: parsed.reject_reason || '',
      confidence_no_website: Number(parsed.confidence_no_website) || 0,
      notes: String(parsed.notes || '').slice(0, 200)
    };
  }
} catch (e) { ai.confidence_no_website = 0; }
let score = ai.confidence_no_website;
const hardReject = lead.hard_reject || '';
if (hardReject || ai.website_found) score = 0;
if (lead.err_q1) score -= 10;
if (lead.err_q2) score -= 10;
if (lead.err_q4) score -= 10;
if (!lead.phone) score -= 5;
const TRADE_WORDS = ['handyman','services','service','construction','roofing','home','repair','llc','contracting','remodeling','plumbing','electric','electrical','hvac','painting','landscaping','company','co','inc','the','solutions','pros','builders','carpentry','fencing','decking','gutters','siding','concrete','excavating'];
const nameWords = String(lead.business_name || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
const generic = nameWords.length <= 2 && nameWords.every(w => TRADE_WORDS.indexOf(w) !== -1);
if (generic) score -= 5;
score = Math.max(0, Math.min(100, score));
const approved = !ai.website_found && !hardReject && score >= 95;
const review = !ai.website_found && !hardReject && !approved && score >= 90;
const reject_reason = hardReject || ai.reject_reason || (ai.website_found ? 'Website found' : 'Confidence below 95');
const website_found = (ai.website_found || hardReject) ? (lead.website_found_url || ai.website_url || '') : '';
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
const notes = approved
  ? ['Google name search checked','Phone search checked','Address search checked','GBP checked','Directory scan complete','Social scan complete','Domain discovery complete (' + lead.domain_probe_count + ' domains)','No website found','AI confidence ' + ai.confidence_no_website + (ai.notes ? ' - ' + ai.notes : '')].join('; ')
  : review
  ? 'REVIEW: ' + reject_reason + '; No website found in any layer; ' + ['Google name search checked','Phone search checked','Address search checked','GBP checked','Directory scan complete','Social scan complete','Domain discovery complete (' + lead.domain_probe_count + ' domains)','AI confidence ' + ai.confidence_no_website + (ai.notes ? ' - ' + ai.notes : '')].join('; ')
  : 'REJECTED: ' + reject_reason + (website_found ? ' -> ' + website_found : '') + (ai.notes ? ' - ' + ai.notes : '');
return [{ json: Object.assign({}, lead, {
  ai_website_found: ai.website_found || !!hardReject,
  ai_confidence: ai.confidence_no_website,
  final_status: approved ? 'approved' : (review ? 'review' : 'rejected'),
  final_confidence: score,
  final_reject_reason: approved ? '' : reject_reason,
  final_website_found: website_found,
  final_notes: notes,
  checked_date: today
}) }];

const lead = $('Scoring + Verdict').item.json;
const isApproved = lead.final_status === 'approved';
const isLikely = !isApproved && lead.final_status === 'review' && (Number(lead.final_confidence) || 0) >= 90;
if (!isApproved && !isLikely) return [{ json: { action: 'none' } }];
let existing = [];
try { existing = String($('Dedupe Phones').first().json.existingPhones || '').split(','); } catch (e) {}
const d = String(lead.phone || '').replace(/\D/g, '').slice(-10);
if (d && existing.indexOf(d) !== -1) return [{ json: { action: 'duplicate' } }];
const owner = String(lead.owner || '').trim();
if (isApproved && String(lead.email || '').trim()) {
  return [{ json: { action: 'leads',
    business_name: lead.business_name, category: lead.category, city: lead.city, phone: lead.phone,
    email: lead.email, source: lead.source, added_date: lead.added_date || lead.checked_date,
    site_status: 'none', site_notes: lead.final_notes } }];
}
return [{ json: { action: 'calllist',
  business_name: lead.business_name, category: lead.category, city: lead.city, phone: lead.phone,
  rating: lead.rating, reviews: lead.reviews, added_date: lead.added_date || lead.checked_date, source: lead.source,
  notes: (isApproved ? 'VERIFIED no website, score ' : 'LIKELY no website, score ') + lead.final_confidence + ', ' + (lead.reviews || '0') + ' reviews' + (owner ? '. Ask for ' + owner : '') } }];

const leads = $('Read Leads Tab').all().map(i => i.json);
let calls = [];
try { calls = $('Read Call List Tab').all().map(i => i.json); } catch (e) { calls = []; }
const digits = v => String(v == null ? '' : v).replace(/\D/g, '');
const phones = new Set();
for (const r of leads.concat(calls)) { const d = digits(r.phone); if (d.length >= 7) phones.add(d.slice(-10)); }
return [{ json: { existingPhones: Array.from(phones).join(',') } }];
